'use strict';

// A private helper this package never publishes: a fast path for inputs it
// already knows are safe. Nothing here is reassigned, nothing conditional,
// nothing stale -- so neither RWF-013 nor RWF-013b has anything to say
// about it. It is an ordinary, honest, unrelated function that happens to
// be spelled the same way as a published export.
//
// That coincidence is the entire attack. `dangerousOp` is a natural name
// for both a package's headline API and its internal helper, and real
// CommonJS packages collide this way constantly.
function dangerousOp(input) {
  return 'safe:' + String(input);
}

// The real implementations, assembled into a dispatch table. This is the
// dominant way a CommonJS package of any size wires itself up, and the
// value the advisory names lives behind a PROPERTY of it -- an expression
// VulnTrace models no value flow through, and must therefore leave
// unresolved rather than guess at.
const impls = {
  native: require('./lib/native'),
  fallback: dangerousOp,
};

// GHSA-vt2v2-0001 names THIS export. At runtime it holds lib/native.js's
// function -- never the declaration above.
exports.dangerousOp = impls.native;

// The same function object, published under a second name for callers that
// want to be explicit. Statically resolvable (RWF-004a), unlike the
// property access above, so the call graph reaches lib/native.js's real
// function through this name.
exports.dangerousOpNative = require('./lib/native');
